"""Generate peoxide-core/src/ordinals.rs from pefile's ordlookup tables.

Usage: python scripts/gen_ordinals.py   (then run cargo fmt)
"""

from pathlib import Path

import ordlookup

OUT = Path(__file__).resolve().parent.parent / "peoxide-core" / "src" / "ordinals.rs"


def rust_bytes(name):
    text = name.decode("ascii")
    assert '"' not in text and "\\" not in text, name
    return f'b"{text}"'


def main():
    lines = [
        "//! Ordinal-to-name tables for DLLs that are usually imported by ordinal.",
        "//! Generated by scripts/gen_ordinals.py from pefile's `ordlookup` package (MIT licensed).",
        "//! Do not edit by hand.",
        "",
    ]
    consts = []
    for dll, names in sorted(ordlookup.ords.items()):
        const = dll.decode("ascii").split(".")[0].upper()
        consts.append((dll, const))
        lines.append(f"const {const}: &[(u16, &[u8])] = &[")
        lines += [f"    ({ordinal}, {rust_bytes(name)})," for ordinal, name in sorted(names.items())]
        lines += ["];", ""]
    lines.append("/// Lowercase DLL name to its ordinal table, sorted by ordinal.")
    lines.append("pub(crate) const TABLES: &[(&[u8], &[(u16, &[u8])])] = &[")
    lines += [f"    ({rust_bytes(dll)}, {const})," for dll, const in consts]
    lines.append("];")
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {OUT} ({sum(len(n) for n in ordlookup.ords.values())} ordinals)")


if __name__ == "__main__":
    main()
